}
/**
 * The non-archived campaigns, oldest first, as card-ready DTOs.
 * POST /donation-campaigns/v2/donation-campaigns/query  { query: { filter: { archived: false }, sort: [{ fieldName: "createdDate", order: "ASC" }], cursorPaging: { limit } } }
 */
export async function fetchCampaigns({ limit = 100 } = {}) {
    const res = await wixRequest(`${BASE}/query`, { body: { query: campaignsQuery({ limit }) } });
    const items = (res?.donationCampaigns ?? []).filter((raw) => !isArchived(raw));
    const metrics = await Promise.all(items.map((raw) => (raw.campaignGoal ? metricsOf(rawId(raw)) : Promise.resolve([]))));
