export async function fetchCampaign(campaignId) {
    let raw;
    try {
        raw = (await wixRequest(`${BASE}/${campaignId}`, { method: "GET" }))?.donationCampaign;
    }
    catch (e) {
        if (e instanceof WixApiError && e.status === 404)
            return null;
        throw e;
    }
    if (!raw || isArchived(raw))
